var jvar_item_url = "";
if (jelly.jvar_item.getType() == 'external')
    jvar_item_url = GlideappCatalogURLGenerator.getItemBaseURL(jelly.jvar_item);
else
    jvar_item_url = GlideappCatalogURLGenerator.getItemURL(jelly.jvar_item, jelly.jvar_catalog, jelly.jvar_catalog_view, jelly.jvar_category.getID(), jelly.jvar_hint, jelly.RP);
jvar_item_url;

var params = {"sysparm_parent_sys_id":jelly.RP.getParameterValue("sysparm_parent_sys_id"), "sysparm_processing_hint":jelly.RP.getParameterValue("sysparm_processing_hint"), "sysparm_parent_table":jelly.RP.getParameterValue("sysparm_parent_table"), "sysparm_view":jelly.RP.getParameterValue("sysparm_view")};
var jvar_view_all_url = GlideappCatalogURLGenerator.getHomepageCategoryLinkWithParams(jelly.jvar_catalog, jelly.jvar_catalog_view, jelly.jvar_category.getID(), params);
jvar_view_all_url;
